<?php
declare(strict_types=1);require __DIR__.'/bootstrap.php';$error='';$success='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$action=$_POST['action']??'';if($action==='save'){$id=(int)($_POST['id']??0);$title=trim((string)($_POST['title']??''));$slug=slugify((string)(($_POST['slug']??'')?:$title));$image=trim((string)($_POST['cover_image']??''));$url=trim((string)($_POST['project_url']??''));foreach([$image,$url] as $link){if($link!==''&&!filter_var($link,FILTER_VALIDATE_URL))throw new RuntimeException('Link düzgün URL formatında olmalıdır.');}if($title==='')throw new RuntimeException('Layihə adı mütləqdir.');$args=[$title,$slug,trim((string)($_POST['summary']??'')),trim((string)($_POST['description']??'')),$image?:null,$url?:null,(int)($_POST['sort_order']??0),isset($_POST['is_published'])?1:0];if($id){$q=$pdo->prepare('UPDATE projects SET title=?,slug=?,summary=?,description=?,cover_image=?,project_url=?,sort_order=?,is_published=? WHERE id=?');$q->execute([...$args,$id]);}else{$q=$pdo->prepare('INSERT INTO projects(title,slug,summary,description,cover_image,project_url,sort_order,is_published) VALUES(?,?,?,?,?,?,?,?)');$q->execute($args);}$success='Layihə yadda saxlanıldı.';}elseif($action==='delete'){$q=$pdo->prepare('DELETE FROM projects WHERE id=?');$q->execute([(int)$_POST['id']]);$success='Layihə silindi.';}}catch(Throwable $x){$error=$x instanceof PDOException?'Slug təkrarlanır və ya məlumat bazası xətası.':$x->getMessage();}}
$edit=null;if(isset($_GET['edit'])){$q=$pdo->prepare('SELECT * FROM projects WHERE id=?');$q->execute([(int)$_GET['edit']]);$edit=$q->fetch()?:null;}$rows=$pdo->query('SELECT * FROM projects ORDER BY sort_order,id DESC')->fetchAll();admin_header('Layihələr','projects');?>
<?php if($error):?><div class="notice error"><?=e($error)?></div><?php endif;?><?php if($success):?><div class="notice success"><?=e($success)?></div><?php endif;?>
<div class="content-grid"><section class="panel"><h2><?= $edit?'Layihəni redaktə et':'Yeni layihə' ?></h2><form class="admin-form" method="post"><?=csrf_field()?><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=e((string)($edit['id']??0))?>"><label>Layihə adı<input name="title" required maxlength="220" value="<?=e($edit['title']??'')?>"></label><label>Slug<input name="slug" value="<?=e($edit['slug']??'')?>"></label><label>Qısa xülasə<textarea name="summary" rows="3"><?=e($edit['summary']??'')?></textarea></label><label>Ətraflı məlumat<textarea name="description" rows="6"><?=e($edit['description']??'')?></textarea></label><label>Cover şəkil URL<input type="url" name="cover_image" value="<?=e($edit['cover_image']??'')?>"></label><label>Layihə linki<input type="url" name="project_url" value="<?=e($edit['project_url']??'')?>"></label><label>Sıralama<input type="number" name="sort_order" value="<?=e((string)($edit['sort_order']??0))?>"></label><label class="check-label"><input type="checkbox" name="is_published" <?=(!$edit||!empty($edit['is_published']))?'checked':''?>> Saytda göstər</label><div class="form-actions"><button class="btn-admin">Yadda saxla</button><?php if($edit):?><a class="btn-secondary" href="projects.php">Ləğv et</a><?php endif;?></div></form></section>
<section class="panel"><h2>Layihə siyahısı</h2><div class="table-wrap"><table><thead><tr><th>Layihə</th><th>Status</th><th>Əməliyyat</th></tr></thead><tbody><?php foreach($rows as $p):?><tr><td><b><?=e($p['title'])?></b><small class="subline"><?=e($p['slug'])?></small></td><td><?=$p['is_published']?'Dərc edilib':'Gizli'?></td><td class="actions"><a href="?edit=<?=$p['id']?>">Redaktə</a><form method="post" onsubmit="return confirm('Layihə silinsin?')"><?=csrf_field()?><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$p['id']?>"><button class="link-danger">Sil</button></form></td></tr><?php endforeach;?></tbody></table></div></section></div><?php admin_footer();?>